    return Math.multiplyExact(price, quantity);
  }
  public static void main(String[] args) {
    System.out.println(total(12, 3));
    System.out.println(total(12, 0));
    try { total(12, -1); }
    catch (IllegalArgumentException error) { System.out.println("Invalid input rejected"); }
  }
}

