import java.util.ArrayList;

public class Main {
  public static void main(String[] args) {
    Catalog catalog = new Catalog();
    catalog.add(new Book("Java 101", "Smith"));
    catalog.add(new Book("Clean Code", "Martin"));
    catalog.add(new Book("Java Now", "Smith"));

    System.out.println(catalog.size());
    System.out.println(catalog.findByTitle("Clean Code"));
    System.out.println(catalog.findByTitle("Unknown"));

    for (Book b : catalog.byAuthor("Smith")) {
      System.out.println(b.title);
    }
  }
}

class Book {
  String title;
  String author;

  Book(String title, String author) {
    this.title = title;
    this.author = author;
  }

  @Override
  public String toString() {
    return title + " by " + author;
  }
}

class Catalog {
  ArrayList<Book> books = new ArrayList<>();

  void add(Book book) {
    books.add(book);
  }

  int size() {
    return books.size();
  }

  Book findByTitle(String title) {
    for (Book b : books) {
      if (b.title.equals(title)) return b;
    }
    return null;
  }

  ArrayList<Book> byAuthor(String author) {
    ArrayList<Book> result = new ArrayList<>();
    for (Book b : books) {
      if (b.author.equals(author)) result.add(b);
    }
    return result;
  }
}

