import java.util.ArrayList;

public class Main {
  public static void main(String[] args) {
    Library library = new Library();
    library.addBook("Java 101");
    library.addBook("Clean Code");

    System.out.println(library.checkout("Java 101"));
    System.out.println(library.checkout("Java 101"));
    System.out.println(library.returnBook("Java 101"));
    System.out.println(library.checkout("Java 101"));

    library.addBook("Algorithms");
    library.addBook("Java Now");
    System.out.println(library.report());
  }
}

class Library {
  ArrayList<String> available = new ArrayList<>();

  void addBook(String title) {
    available.add(title);
  }

  boolean checkout(String title) {
    return available.remove(title);
  }

  boolean returnBook(String title) {
    if (available.contains(title)) {
      return false;
    }
    available.add(title);
    return true;
  }

  String report() {
    return "Available books: " + available.size();
  }
}

